echo OK nox-chat-rq.js $(wc -c <nox-chat-rq.js)
cd /workspace/nox/web/site
sed -i "s#nox-chat-rq.js?v=[0-9]*#nox-chat-rq.js?v=$(date +%s)#" chat.html
echo "== pages scan"
for f in *.html; do
  m=0; grep -q "nox-minichat.js" $f && m=1
  mm=0; grep -q "nox-mini.js" $f && mm=1
  echo "$f minichat=$m mini=$mm"
done | grep -v "minichat=1 mini=\|minichat=0 mini=1" | head -80
echo "== count"; ls *.html | wc -l
head -c 1200 nox-minichat.js
